import json,re,html
from pathlib import Path
w=Path('curation/workspace/atypical-hus')
records=json.load(open(w/'sources/primary-records.json'))+json.load(open(w/'sources/additional-primary-records.json'))
pubs={x['id']:x for x in records}
selected=['17495132','18006700','23431077','25037630','37954621','18796626','23738544','39848404','30910380','19877009','17914026']
for i in selected:pubs[i]['abstractText']=re.sub(r'<(?!/?[A-Za-z])','&lt;',pubs[i].get('abstractText',''));pubs[i]['inspectedScope']='Europe PMC primary-report core abstract and metadata inspected by Codex agent 2026-10-17; no full methods appraisal'
pubs['37954621']['inspectedScope']+='; PMC10634509 full text methods/results/discussion inspected'
def entity(id,label,cls,desc):return dict(id='entity-'+id,label=label,entityClass=cls,description=desc,synonyms=[],externalIds=[])
entities=[
entity('complement-regulatory-variants','Complement-regulatory gene variants','process','Selected CFH, CFI and CD46 susceptibility variants; variant-specific functional evidence and incomplete penetrance are retained.'),
entity('factor-h','Factor H regulatory activity','protein','Surface recognition and complement regulation; patient autoantibody binding and inhibition are studied in biochemical assays.'),
entity('anti-factor-h','Anti-factor H autoantibodies','antibody','Patient antibodies to factor H; studied C-terminal binding inhibits surface recognition.'),
entity('ahus-cfhr-deficiency','CFHR1/CFHR3 deficiency','process','Inherited deficiency associated with anti-factor H autoantibodies in a selected cohort; not sufficient by itself to establish disease.'),
entity('ahus-factor-i','Factor I regulatory activity','protein','Complement protease activity; selected CFI variants impair secretion or surface C3b cleavage.'),
entity('ahus-cd46','CD46 surface regulation','protein','Membrane cofactor protein function; R69W/A304V cell challenge experiments retain variant and model limits.'),
entity('ahus-c3-variants','C3 susceptibility variants','process','Selected C3 variants in a low-C3 patient series; both gain-of-function and inactivating variants were reported.'),
entity('ap-dysregulation','Alternative complement pathway dysregulation','process','Failure to regulate alternative complement activity; fluid phase and endothelial-surface readouts are distinct.'),
entity('ahus-serum','aHUS patient serum','process','Patient serum sampled during acute disease or remission, tested on human endothelial cells.'),
entity('ahus-mac','Endothelial C5b-9 deposition','process','Terminal complement membrane attack complex on endothelial surfaces; assay readout is not equivalent to clinical disease.'),
entity('ahus-c5ar1','C5a–C5aR1 signalling','process','Terminal complement inflammatory signalling, genetically and pharmacologically perturbed in distinct mouse models.'),
entity('ahus-tma','Renal thrombotic microangiopathy','process','Renal small-vessel pathology in mouse experiments; human trial outcomes use their specified TMA definitions.'),
entity('ahus-macrothrombosis','Macrovascular thrombosis','clinical_outcome','Separate outcome in factor H mutant mice; not substituted for renal TMA or universal human disease.'),
entity('ahus-susceptibility','aHUS susceptibility / penetrance','clinical_outcome','Human genetic association and incomplete penetrance; not a deterministic genotype-to-disease pathway.'),
entity('ahus-eculizumab','Eculizumab exposure','process','C5 inhibitor exposure in endothelial assays and separate uncontrolled clinical trials.'),
entity('ahus-tma-response','Clinical TMA response','clinical_outcome','Trial-specific platelet and TMA event-free outcomes; not identical across studies.'),
entity('kidney-function-loss','Loss of kidney function','clinical_outcome','Renal impairment or recovery endpoints in selected aHUS trials; reversal is not assured.'),
entity('ahus-c5','Complement C5 cleavage','process','Terminal complement activation target of eculizumab and ravulizumab; both C5a and C5b-9 pathways are downstream.')]
f=[]
def add(id,pmid,sub,obj,pred,text,quote,system,lim,typ='human_in_vitro',interp='mechanistic',category='supporting'):
 raw=pubs[pmid]['abstractText'];assert quote in html.unescape(raw),(id,quote)
 f.append(dict(id='ahus-'+id,pmid=pmid,subject='entity-'+sub,object='entity-'+obj,predicate=pred,text=text,quote=quote,quoteLocation='Primary-report abstract, Europe PMC core record',studySystem=system,limitations=[lim,'Selected primary-source inspection by an agent; independent domain review pending.'],category=category,evidenceType=typ,causalInterpretation=interp,sourceCheck={'checkedBy':'Codex agent (source inspection; not human domain approval)','checkedAt':'2026-10-17'}))
add('fh-block','17495132','anti-factor-h','factor-h','inhibits','IgG from five unrelated aHUS patients inhibited factor H binding to C3b in a functional assay.','isolated patient IgG inhibited FH binding to C3b','Five patient IgG preparations; recombinant fragments and biochemical binding assay','Sheep-erythrocyte hemolysis experiments do not directly demonstrate human renal endothelial injury.')
add('cfhr-antibody','18006700','ahus-cfhr-deficiency','anti-factor-h','is_associated_with','In 147 aHUS patients, 16 juvenile autoantibody-positive patients had absent or very low CFHR1/CFHR3.','16 juvenile individuals','147-patient cohort; CFHR protein levels and autoantibody mapping','Association does not establish that deletion causes autoantibodies or that deficiency is sufficient for aHUS.','human_genetic','association')
add('genetic-risk','23431077','complement-regulatory-variants','ahus-susceptibility','is_associated_with','Among 795 aHUS patients, single complement-gene mutations were detected in 41% and combined mutations in 3%.','single mutations in 41% and combined mutations in 3%','Human multicentre genetic cohort; 795 patients','Historical mutation classification and selected ascertainment; current variant reclassification not performed.','human_genetic','association')
add('penetrance','23431077','complement-regulatory-variants','ahus-susceptibility','is_associated_with','Penetrance among combined-mutation carriers differed with CFH/MCP risk haplotypes: 73% with two versus 36% with zero or one.','73% penetrance among carriers with two risk haplotypes compared with 36% penetrance','Human family and genotype–phenotype analysis','Susceptibility variants do not determine clinical disease; estimates are cohort-specific.','human_genetic','association','qualifying')
add('fi-function','19877009','ahus-factor-i','ap-dysregulation','inhibits','In expression and endothelial assays, selected CFI variants impaired secretion or surface C3b degradation relative to wild type.','Three mutants cleaved surface-bound C3b less efficiently than WT','Human HEK293 expression; purified proteins; endothelial-cell complement assays','Variant-specific function; not every CFI variant is pathogenic or has the same defect.')
add('cd46-function','17914026','ahus-cd46','ap-dysregulation','inhibits','Cell lines expressing CD46 R69W or A304V controlled alternative-pathway surface activation less effectively than wild-type protein.','deficient in their ability to control the alternative pathway of complement activation on a cell surface','Permanent cell lines expressing human CD46 variants; complement challenge','Mixed clinical phenotypes in the report; functional impairment alone does not establish aHUS-specific pathogenicity.')
add('c3-risk','18796626','ahus-c3-variants','ahus-susceptibility','is_associated_with','Nine novel C3 mutations were described in 14 selected aHUS patients with persistently low C3.','9 novel C3 mutations in 14 aHUS patients','Selected human low-C3 case series and functional analysis','Not a prevalence estimate for unselected aHUS.','human_genetic','association')
add('c3-heterogeneity','18796626','ahus-c3-variants','ahus-susceptibility','is_associated_with','The C3 series reported five gain-of-function and two inactivating mutations, qualifying any uniform gain-of-function interpretation.','5 of these mutations are gain-of-function and 2 are inactivating','Human C3 mutation functional analysis','Not all identified variants were shown to have the same functional consequence.','human_genetic','association','qualifying')
add('serum-mac','25037630','ahus-serum','ahus-mac','activates','Acute aHUS serum induced greater C3 and C5b-9 deposition than control serum on unstimulated HMEC-1.','Acute aHUS serum, but not serum from remission','Human serum and HMEC-1 culture; 44 patients and relatives','Culture deposition cannot be interpreted as a validated clinical activity test.')
add('carrier-mac','25037630','ahus-serum','ahus-mac','activates','On ADP-activated HMEC-1, serum from unaffected mutation carriers also induced excessive complement deposition.','from all unaffected mutation carriers','Serum from relatives and patients; ADP-activated human HMEC-1','Abnormal assay response is not sufficient for clinical aHUS and depends on cell activation.','human_in_vitro','mechanistic','qualifying')
add('glomerular-mac','37954621','ahus-serum','ahus-mac','activates','Acute-phase sera from five aHUS patients increased C5b-9 deposition on glomerular microvascular endothelial cells.','Sera from acute disease phases of all patients showed increased endothelial C5b-9 deposition','Five patients; control conditionally immortalized human glomerular endothelial cells','Small sample and culture model; magnitude did not perfectly track clinical severity.')
add('remission-mac','37954621','ahus-serum','ahus-mac','activates','Remission samples normalized C5b-9 deposition with or without ongoing eculizumab complement blockade.','whether remission was reached with or without complement blockage by eculizumab','Longitudinal patient serum on human glomerular endothelial cultures','Qualifies disease-activity and drug-response interpretation; assay is not sufficient to infer treatment need.','human_in_vitro','mechanistic','qualifying')
add('ecu-mac','37954621','ahus-eculizumab','ahus-mac','inhibits','Eculizumab dose-dependently inhibited activated-serum C5b-9 deposition on glomerular endothelial cultures.','could be dose-dependently inhibited by adding the C5 inhibitor eculizumab','Zymosan-activated human serum and glomerular endothelial cells','Zymosan may also activate endothelial cells; no clinical efficacy estimate from this experiment.')
add('mac-tma','39848404','ahus-mac','ahus-tma','contributes_to','In C3 D1115N mice, C7 deficiency abolished clinical and histological disease, supporting a requirement for MAC in that model.','C7 deficiency completely abolished both clinical and histological evidence of disease','C3 D1115N knock-in mice; C7 knockout and therapeutic anti-C7 perturbation','Mouse-model causal evidence; does not establish anti-C7 clinical efficacy or universal human dependence.','animal_experiment','mechanistic')
add('c5ar-tma','39848404','ahus-c5ar1','ahus-tma','contributes_to','C5aR1 removal attenuated clinical disease risk in C3 D1115N mice but renal TMA still developed.','mice still developed thrombotic microangiopathy','C3 D1115N mice crossed with C5aR1-deficient mice','C5aR1 contribution is model-specific; not equivalent to MAC blockade.','animal_experiment','mechanistic','supporting')
add('fh-mac-tma','30910380','ahus-mac','ahus-tma','contributes_to','C6 or C9 deficiency markedly diminished renal TMA in factor H W1206R mutant mice.','C6 or C9 deficiency significantly improved survival and markedly diminished renal TMA','Factor H W1206R mouse; C6/C9 genetic deficiency','Aged deficient mice developed C3GN-like disease; terminal blockade does not normalize all upstream biology.','animal_experiment','mechanistic')
add('fh-c5ar-macro','30910380','ahus-c5ar1','ahus-macrothrombosis','contributes_to','C5aR1 deficiency prevented macrovascular thrombosis in factor H mutant mice.','C5aR1 gene deficiency prevented macrovascular thrombosis','Factor H W1206R mouse; C5aR1 genetic deficiency','Macrovascular thrombosis is a distinct mouse outcome; not a claim of universal human aHUS manifestations.','animal_experiment','mechanistic')
add('fh-c5ar-renal','30910380','ahus-c5ar1','ahus-tma','contributes_to','C5aR1 deficiency did not reduce renal TMA or improve survival in factor H mutant mice.','did not improve survival or reduce renal TMA','Factor H W1206R mouse; C5aR1 genetic deficiency','Null renal outcome qualifies pathway generalization; differs from clinical-risk attenuation in the C3 model.','animal_experiment','mechanistic','qualifying')
add('ecu-response','23738544','ahus-eculizumab','ahus-tma-response','contributes_to','In two prospective uncontrolled eculizumab phase 2 studies, platelet counts improved and 80% in the second trial achieved TMA event-free status.','80% of the patients had thrombotic microangiopathy event-free status','37 patients aged at least 12 years; two prospective single-arm phase 2 trials','No concurrent randomized comparator; event-free status differs from complete TMA response.','human_observational','interventional')
add('ecu-renal','23738544','ahus-eculizumab','kidney-function-loss','inhibits','Renal function improved during eculizumab treatment; four of five baseline dialysis patients in trial 1 discontinued dialysis.','dialysis was discontinued in 4 of 5 patients','Two prospective single-arm phase 2 studies; distinct severity cohorts','Small selected cohorts; no guarantee of renal recovery and no untreated comparator.','human_observational','interventional')
profile=json.load(open('knowledge/diseases/atypical-hus/disease.json'))
aliases=['aHUS','complement-mediated HUS','complement-mediated thrombotic microangiopathy','CM-TMA']
profile['aliases']=aliases;Path('knowledge/diseases/atypical-hus/disease.json').write_text(json.dumps(profile,indent=2)+'\n')
b=dict(version=1,id='atypical-hus-candidate-20261017-01',evidenceCutoff='2026-10-17',diseaseDescription=profile['summary']+' Selected genetic, antibody, endothelial-assay and terminal-pathway studies only. Factor B, THBD, triggers and full clinical manifestation sequence remain deferred rather than inferred.',diseaseAliases=aliases,context=dict(id='context-ahus-overview',label='Bounded cross-study overview; human assays, genetics, mouse experiments and treatment studies require separate views',organism='Human studies and separate mouse experiments',phenotype='Selected complement-mediated aHUS mechanisms',tissue='Circulation and renal microvasculature',stage='Selected primary reports; not a complete natural history'),entities=[e for e in entities if e['id']!='entity-ahus-c5'],publications=[pubs[i] for i in selected],findings=f,positions=[dict(entityId=e['id'],x=50+(i%4)*360,y=50+(i//4)*230) for i,e in enumerate([e for e in entities if e['id']!='entity-ahus-c5'])],groups=[],releaseNote='Agent-curated local candidate; independent scientific review and calibration pending. Abstract access predominates; notice-linked factor B and ravulizumab primary results deferred pending correction appraisal.')
(w/'first-map.json').write_text(json.dumps(b,indent=2)+'\n')
print(len(entities),len(f),len(selected))
